  LZ_refresh();
  LZ_toast('✔ 已切换到 '+s);
  return 'ok';
}

// ---------- 按钮：检查登录状态 ----------
function LZ_checkLogin(){
  var b=LZ_base2();
  var ck='';
  try{ ck=String(java.getCookie(b,null)||''); }catch(e){}
  if(!ck||ck.indexOf('token')<0){
    if(ck.indexOf('litchi.session')<0){
      LZ_toast('ℹ 当前为游客状态（未登录）\n搜索 / 发现 / 播放均可正常使用\n登录仅用于收藏、追剧、观看记录同步');
      return 'guest';
    }
  }
  // 尝试拉取用户信息
  var r=LZ_req(b+'/api/v1/user/profile',8000);
  if(r.ok&&r.html){
    var t=r.html;
    if(t.indexOf('"success":true')>=0||t.indexOf('"success": true')>=0){
      var nm=t.match(/"(?:nickName|nickname|loginName|userName)"\s*:\s*"([^"]*)"/);
      LZ_toast('✔ 已登录'+(nm?('：'+nm[1]):'')+'\n收藏/追剧/观看记录已同步');
      return 'ok';
