  return u;
}
function LZ_req(u,ms){
  var t0=Date.now();
  try{
    var r=java.ajax(u+','+JSON.stringify({timeout:ms||8000,headers:{'User-Agent':LZ_ua2(),'Accept':'text/html,application/xhtml+xml,*/*;q=0.8'}}));
    var dt=Date.now()-t0;
    var s=(r==null)?'':String(r);
    return {ok:true,ms:dt,len:s.length,html:s,url:u};
  }catch(e){
    return {ok:false,ms:(Date.now()-t0),len:0,html:'',err:String(e&&e.message?e.message:e),url:u};
  }
}

// ---------- 发布页抓线路 ----------
// /road/ 页脚与 NUXT 数据里都带 liz01~liz10.com 线路
function LZ_pickDomains(html){
  var out=[];
  if(!html) return out;
  var re=/https?:\/\/(liz\d{2}\.com)/g;
  var m;
  while((m=re.exec(html))!=null){
    var u='https://'+m[1];
    if(out.indexOf(u)<0) out.push(u);
  }
  return out;
}

// ---------- 按钮：从发布页获取网址 ----------
function LZ_fromRoad(){
  var pub=String(source.get('lizroad')||'').trim();
  if(pub.length<6){ pub='https://liz04.com/road/'; }
  if(pub.indexOf('http')!=0){ pub='https://'+pub.replace(/^\/+/,''); }
  if(pub.charAt(pub.length-1)!='/') pub=pub+'/';
  LZ_toast('正在读取发布页：'+pub);
  var r=LZ_req(pub,12000);
  if(!r.ok||r.len<500){
    LZ_toast('✖ 发布页读取失败，请检查网络或手动输入发布页地址');
    return 'fail';
  }
  var ds=LZ_pickDomains(r.html);
  if(ds.length==0){
    LZ_toast('✖ 发布页中未解析到线路地址');
    return 'fail';
  }
  // 去重 + 只保留 http/https
  var list=[];
  for(var i=0;i<ds.length;i++){ if(list.indexOf(ds[i])<0) list.push(ds[i]); }
  source.put('lizlines',list.join(','));
  LZ_toast('✔ 已从发布页获取 '+list.length+' 条线路，点「⚡ 测速选最快」自动选择');
  return 'ok';
}

// ---------- 测速结果辅助 ----------
function LZ_spKey(host){
  var m=String(host||'').match(/liz(\d{2})\.com/);
  if(m) return 'lizsp'+m[1];
  return 'lizsp_'+String(host||'').replace(/[^a-z0-9]/gi,'').substring(0,8);
}
function LZ_spClear(){
  for(var p=1;p<=10;p++){ try{ source.put('lizsp'+('0'+p).slice(-2),''); }catch(e){} }
}
function LZ_refresh(){
  try{ java.reLoginView(); return true; }catch(e){}
  try{ java.reUiView(); return true; }catch(e2){}
  return false;
}

// ---------- 按钮：测速选最快 ----------
function LZ_speed(){
  var raw=String(source.get('lizlines')||'');
  var list=[];
  if(raw.length>6){
    var a=raw.split(',');
    for(var i=0;i<a.length;i++){
      var s=String(a[i]||'').trim();
      if(s.length>6){ if(s.indexOf('http')!=0) s='https://'+s; list.push(s.replace(/\/+$/,'')); }
    }
  }
  if(list.length==0){
    list=['https://liz04.com','https://liz03.com','https://liz01.com','https://liz02.com','https://liz05.com','https://liz06.com','https://liz07.com','https://liz08.com','https://liz09.com','https://liz10.com'];
  }
  LZ_spClear();
  LZ_toast('正在测速 '+list.length+' 条线路…');
  var best=null,bestMs=999999;
  var msg=[];
  for(var i=0;i<list.length;i++){
    var host=list[i];
    var r=LZ_req(host+'/',8000);
    var tag='';
    if(r.ok&&r.len>2000){
      tag=r.ms+'ms';
      if(r.ms<bestMs){ bestMs=r.ms; best=host; }
    }else if(r.ok){ tag='内容异常'; }
    else{ tag='超时'; }
    try{ source.put(LZ_spKey(host),tag); }catch(e){}
    msg.push(host.replace('https://','')+' '+tag);
  }
  if(best){
    source.put('lizhost',best);
    try{ source.put(LZ_spKey(best),'⚡'+source.get(LZ_spKey(best))); }catch(e2){}
    var ok=LZ_refresh();
    LZ_toast('⚡ 最快：'+best.replace('https://','')+' '+bestMs+'ms'+(ok?'\n结果已填到各线路按钮':'\n请重新打开登录面板查看结果'));
    return 'ok';
  }
  LZ_refresh();
  LZ_toast('✖ 所有线路均不可达\n'+msg.join(' / '));
  return 'fail';
}

// ---------- 按钮：切换线路 ----------
function LZ_setLine(d){
  if(!d){ LZ_toast('✖ 线路为空'); return 'fail'; }
  var s=String(d).trim();
  if(s.indexOf('http')!=0) s='https://'+s;
  s=s.replace(/\/+$/,'');
  source.put('lizhost',s);
  LZ_refresh();
  LZ_toast('✔ 已切换到 '+s);
  return 'ok';
}

