// ---------- 按钮：打开登录页 ----------
function LZ_openLogin(){
  try{
    java.startBrowser(LZ_base2()+'/user','荔枝短剧 · 登录');
    LZ_toast('已打开登录页，登录成功后返回点「🔄 检查登录状态」');
